        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 28px rgba(37, 99, 235, 0.28);
        transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
      }

      button:hover {
        background: linear-gradient(135deg, var(--primary-hover), #1e40af);
        transform: translateY(-1px);
        box-shadow: 0 14px 32px rgba(37, 99, 235, 0.34);
      }

      button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.3);
        outline-offset: 3px;
      }

      .status {
        margin-top: 18px;
        padding: 14px 16px;
        border-radius: 14px;
        background: rgba(37, 99, 235, 0.08);
        color: #1e3a8a;
        display: none;
      }

      .status.is-visible {
        display: block;
      }

      @media (max-width: 640px) {
        .hero,
        form {
          padding-left: 20px;
          padding-right: 20px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const state = {
        submitted: false,
        touched: {},
        values: {
          fullName: "",
          email: "",
          phone: ""
        }
      };

      const root = document.getElementById("root");

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        return errors;
      }

      function Field({ id, label, type, placeholder, value, helperText, required, autocomplete }) {
        return `
          <div class="form-field">
            <label for="${id}">${escapeHtml(label)}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${escapeHtml(placeholder)}"
              ${required ? "required" : ""}
              autocomplete="${autocomplete}"
              aria-invalid="false"
              aria-describedby="${id}-help ${id}-error"
            />
            <p class="helper-text" id="${id}-help">${escapeHtml(helperText)}</p>
            <p class="error-text" id="${id}-error" hidden></p>
          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <main class="page">
            <section class="card" aria-labelledby="support-form-title">
              <header class="hero">
                <p class="eyebrow">Support</p>
                <h1 id="support-form-title">Contact our team</h1>
                <p class="subtitle">Send us your details and we&apos;ll route your request to the right support specialist.</p>
              </header>

              <form id="contact-form" novalidate>
                <div class="form-grid">
                  ${Field({
                    id: "fullName",
                    label: "Full name",
                    type: "text",
                    placeholder: "Jane Doe",
                    value: state.values.fullName,
                    helperText: "Enter the name you want our team to use when replying.",
                    required: true,
                    autocomplete: "name"
                  })}

                  ${Field({
                    id: "email",
                    label: "Email address",
                    type: "email",
                    placeholder: "jane@company.com",
                    value: state.values.email,
                    helperText: "We'll send updates and follow-up questions here.",
                    required: true,
                    autocomplete: "email"
                  })}

                  ${Field({
                    id: "phone",
                    label: "Phone number",
                    type: "tel",
                    placeholder: "+1 (555) 123-4567",
                    value: state.values.phone,
                    helperText: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
                    required: false,
                    autocomplete: "tel"
                  })}
                </div>

                <div class="actions">
                  <button type="submit">Submit request</button>
                </div>

                <div class="status ${state.submitted ? "is-visible" : ""}" role="status">
                  Thanks — your message is ready to send.
                </div>
              </form>
            </section>
          </main>
        `;
      }

      function render() {
        root.innerHTML = SupportContactForm();
        wireEvents();
        syncAll();
      }

      function syncField(name) {
        const errors = validate(state.values);
        const input = document.getElementById(name);
        const errorNode = document.getElementById(`${name}-error`);
        const showError = state.submitted || state.touched[name];
        const message = showError ? errors[name] || "" : "";

        if (input) {
          input.setAttribute("aria-invalid", message ? "true" : "false");
        }

        if (errorNode) {
          errorNode.textContent = message;
          errorNode.hidden = !message;
        }
      }

      function syncStatus() {
        const status = document.querySelector(".status");
        if (status) {
          status.classList.toggle("is-visible", state.submitted);
        }
      }

      function syncAll() {
        ["fullName", "email", "phone"].forEach(syncField);
        syncStatus();
      }

      function wireEvents() {
        const form = document.getElementById("contact-form");

